import { test, expect } from '@playwright/test';

test.describe('PDF Upload and Viewer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should upload a PDF file and display it in the inline viewer', async ({ page }) => {
    const filePath = 'path/to/sample.pdf';
    await page.getByLabel('Upload PDF').setInputFiles(filePath);
    await expect(page.getByText('PDF uploaded successfully')).toBeVisible();
    await expect(page.getByRole('document')).toBeVisible();
  });

  test('should show error message for invalid file type', async ({ page }) => {
    const filePath = 'path/to/sample.txt';
    await page.getByLabel('Upload PDF').setInputFiles(filePath);
    await expect(page.getByText('Invalid file type. Please upload a PDF.')).toBeVisible();
  });
});
